class GameOfLifeTest {

    @Test
    void emptyGridStaysEmpty() {
        assertEquals(Set.of(), GameOfLife.nextGeneration(Set.of()));
    }

    @Test
    void singleCellDiesOfUnderpopulation() {
        assertEquals(Set.of(), GameOfLife.nextGeneration(Set.of(new Cell(0, 0))));
    }

    @Test
    void twoAdjacentCellsWithOneNeighborEachDie() {
        assertEquals(
                Set.of(),
                GameOfLife.nextGeneration(Set.of(new Cell(0, 1), new Cell(1, 1))));
    }

    @Test
    void liveCellWithTwoNeighborsSurvives() {
        Set<Cell> next = GameOfLife.nextGeneration(
                Set.of(new Cell(0, 0), new Cell(0, 1), new Cell(0, 2)));

        assertTrue(next.contains(new Cell(0, 1)));
    }

    @Test
    void liveCellWithThreeNeighborsSurvives() {
        Set<Cell> next = GameOfLife.nextGeneration(
                Set.of(new Cell(0, 0), new Cell(1, 0), new Cell(2, 0), new Cell(1, 1)));

        assertTrue(next.contains(new Cell(1, 0)));
    }

    @Test
    void liveCellWithMoreThanThreeNeighborsDies() {
        Set<Cell> next = GameOfLife.nextGeneration(Set.of(
                new Cell(0, 0), new Cell(1, 0), new Cell(2, 0),
                new Cell(1, 1),
                new Cell(0, 2), new Cell(1, 2), new Cell(2, 2)));

        assertFalse(next.contains(new Cell(1, 1)));
    }

