import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public final class GameOfLife {

    private GameOfLife() {
    }

    public static Set<Cell> nextGeneration(Set<Cell> livingCells) {
        return candidates(livingCells).stream()
                .filter(cell -> isAliveInNextGeneration(cell, livingCells))
                .collect(Collectors.toUnmodifiableSet());
    }

    private static Set<Cell> candidates(Set<Cell> livingCells) {
        return livingCells.stream()
                .flatMap(cell -> Stream.concat(Stream.of(cell), cell.neighbours().stream()))
                .collect(Collectors.toUnmodifiableSet());
    }

    private static boolean isAliveInNextGeneration(Cell cell, Set<Cell> livingCells) {
        long livingNeighbours = livingNeighbourCount(cell, livingCells);
        return livingCells.contains(cell)
                ? ConwayRules.survives(livingNeighbours)
                : ConwayRules.isBorn(livingNeighbours);
    }

    private static long livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
        return cell.neighbours().stream().filter(livingCells::contains).count();
    }
}
