        return candidates(livingCells).stream()
                .filter(cell -> ConwayRules.isAliveNextGeneration(
                        livingCells.contains(cell),
                        livingNeighbourCount(cell, livingCells)))
                .collect(Collectors.toUnmodifiableSet());
    }

    private static Set<Cell> candidates(Set<Cell> livingCells) {
        return livingCells.stream()
                .flatMap(cell -> Stream.concat(Stream.of(cell), cell.neighbours().stream()))
                .collect(Collectors.toUnmodifiableSet());
    }

    private static long livingNeighbourCount(Cell cell, Set<Cell> livingCells) {
        return cell.neighbours().stream().filter(livingCells::contains).count();
    }
}
public final class ConwayRules {

    private ConwayRules() {
    }

    public static boolean isAliveNextGeneration(boolean currentlyAlive, long livingNeighbours) {
        return currentlyAlive
                ? survives(livingNeighbours)
                : isBorn(livingNeighbours);
    }

    private static boolean survives(long livingNeighbours) {
        return livingNeighbours == 2 || livingNeighbours == 3;
    }

    private static boolean isBorn(long livingNeighbours) {
        return livingNeighbours == 3;
    }
}
